export function mount(ctx) {
  // Local selectors keep this example safe to duplicate as a component.
  const card = ctx.el.querySelector('.tilt-object');
  const status = ctx.el.querySelector('.tilt-status');
  const media = window.matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = (value, min, max, fallback) => {
    const number = Number(value);
    return Math.max(min, Math.min(max, Number.isFinite(number) ? number : fallback));
  };
  const limit = clamp(ctx.props.tiltDegrees, 0, 18, 12);
  const response = clamp(ctx.props.responseMs, 40, 400, 120);
  const original = card.style.transform;
  const originalText = status.textContent;
  let selected = false;
  let x = 0, y = 0, targetX = 0, targetY = 0;
  let stopFrame = null, previousTime = 0;

  function stop() {
    if (stopFrame) stopFrame();
    stopFrame = null;
    previousTime = 0;
  }

  function paint() {
    card.style.transform = media.matches ? original :
      `perspective(800px) rotateX(${x}deg) rotateY(${y}deg) rotate(-7deg)`;
  }

  function moveTo(nextX, nextY) {
    targetX = nextX; targetY = nextY;
    if (media.matches) { stop(); x = 0; y = 0; paint(); return; }
    if (stopFrame) return;
    stopFrame = ctx.onFrame(time => {
      const dt = previousTime ? Math.min(40, time - previousTime) : 16;
      previousTime = time;
      const blend = 1 - Math.exp(-dt / response);
      x += (targetX - x) * blend;
      y += (targetY - y) * blend;
      if (Math.abs(targetX - x) + Math.abs(targetY - y) < 0.02) {
        x = targetX; y = targetY; stop();
      }
      paint();
    });
  }

  function rest() { moveTo(selected ? -limit / 2 : 0, selected ? limit : 0); }
  ctx.on('pointermove', event => {
    if (event.pointerType === 'touch' || media.matches) return;
    const bounds = ctx.el.getBoundingClientRect();
    const clamp = value => Math.max(-1, Math.min(1, value));
    moveTo(-clamp((event.clientY - bounds.top) / bounds.height * 2 - 1) * limit,
      clamp((event.clientX - bounds.left) / bounds.width * 2 - 1) * limit);
  });
  ctx.on('pointerleave', rest);
  ctx.on('blur', rest);
  // Native button click also covers touch, Enter and Space.
  ctx.on('click', () => {
    selected = !selected;
    ctx.el.setAttribute('aria-pressed', String(selected));
    status.textContent = selected ? 'Tilt selected · tap to reset' : originalText;
    rest();
  });
  ctx.on(media, 'change', rest);

  return () => {
    stop();
    card.style.transform = original;
    status.textContent = originalText;
    ctx.el.setAttribute('aria-pressed', 'false');
    // ctx also releases every registered listener when preview stops.
  };
}

export function mount(ctx) {
  const wheel = ctx.el.querySelector('.orbit-wheel');
  const status = ctx.el.querySelector('.orbit-status');
  const media = window.matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = (value, min, max, fallback) => {
    const number = Number(value);
    return Math.max(min, Math.min(max, Number.isFinite(number) ? number : fallback));
  };
  const stiffness = clamp(ctx.props.stiffness, 30, 240, 110);
  const damping = clamp(ctx.props.damping, 8, 40, 17);
  const turn = clamp(ctx.props.turnDegrees, 30, 240, 150);
  const original = wheel.style.transform;
  const originalText = status.textContent;
  let expanded = false, angle = 0, velocity = 0, target = 0;
  let stopFrame = null, previousTime = 0;

  function stop() {
    if (stopFrame) stopFrame();
    stopFrame = null;
    previousTime = 0;
  }
  function paint() { wheel.style.transform = `rotate(${angle}deg)`; }
  function settle() {
    stop(); angle = target; velocity = 0; paint();
  }
  function start() {
    if (media.matches) { settle(); return; }
    if (stopFrame) return;
    // A spring runs only after input, then unregisters itself at rest.
    stopFrame = ctx.onFrame(time => {
      const dt = previousTime ? Math.min(0.032, (time - previousTime) / 1000) : 0.016;
      previousTime = time;
      velocity += ((target - angle) * stiffness - velocity * damping) * dt;
      angle += velocity * dt;
      if (Math.abs(target - angle) < 0.02 && Math.abs(velocity) < 0.02) settle();
      else paint();
    });
  }
  ctx.on('click', () => {
    expanded = !expanded;
    target = expanded ? turn : 0;
    ctx.el.setAttribute('aria-pressed', String(expanded));
    status.textContent = expanded ? 'In orbit · tap to return' : originalText;
    start();
  });
  ctx.on(media, 'change', () => { if (media.matches) settle(); });

  return () => {
    stop();
    wheel.style.transform = original;
    status.textContent = originalText;
    ctx.el.setAttribute('aria-pressed', 'false');
  };
}

